  --secondary: #4b4038;
  --secondary-foreground: #ebe4d6;
  --muted: #3b3129;
  --muted-foreground: #c4bdb0;
  --accent: #5a493d;
  --accent-foreground: #ebe4d6;
  --destructive: #b44c38;
  --destructive-foreground: #ffffff;
  --border: #4b4038;
  --input: #4b4038;
  --ring: #c2a180;
  --chart-1: #c2a180;
  --chart-2: #b39171;
  --chart-3: #a87c51;
  --chart-4: #8c6e4e;
  --chart-5: #755b39;
  --radius: 0.25rem;
  --sidebar: #2a2522;
