  --sidebar-primary: #c2a180;
  --sidebar-primary-foreground: #2a2522;
  --sidebar-accent: #5a493d;
  --sidebar-accent-foreground: #ebe4d6;
  --sidebar-border: #4b4038;
  --sidebar-ring: #c2a180;
  --font-sans: Libre Baskerville, serif;
